  `app_code` varchar(64) DEFAULT NULL COMMENT '应用编号',
  `up_title` varchar(200) DEFAULT NULL COMMENT '升级标题',
  `up_content` varchar(1000) DEFAULT NULL COMMENT '升级内容',
  `up_version` decimal(10,0) DEFAULT NULL COMMENT '升级版本',
  `up_type` char(1) DEFAULT NULL COMMENT '升级类型',
  `up_date` date DEFAULT NULL COMMENT '发布时间',
  `apk_url` varchar(500) DEFAULT NULL COMMENT 'APK下载地址',
  `res_url` varchar(500) DEFAULT NULL COMMENT '资源下载地址',
  `status` char(1) NOT NULL DEFAULT '0' COMMENT '状态（0正常 1删除 2停用）',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `remarks` varchar(500) DEFAULT NULL COMMENT '备注信息',
