-- ----------------------------
-- Table structure for js_cms_article
-- ----------------------------
DROP TABLE IF EXISTS `js_cms_article`;
CREATE TABLE `js_cms_article` (
  `id` varchar(64) NOT NULL COMMENT '编号',
  `category_code` varchar(64) NOT NULL COMMENT '栏目编码',
  `module_type` varchar(50) DEFAULT NULL COMMENT '模块类型',
  `title` varchar(255) NOT NULL COMMENT '内容标题',
  `href` varchar(1000) DEFAULT NULL COMMENT '外部链接',
  `color` varchar(50) DEFAULT NULL COMMENT '标题颜色',
  `image` varchar(1000) DEFAULT NULL COMMENT '内容图片',
  `keywords` varchar(500) DEFAULT NULL COMMENT '关键字',
  `description` varchar(500) DEFAULT NULL COMMENT '描述',
  `weight` decimal(10,0) DEFAULT '0' COMMENT '权重，越大越靠前',
  `weight_date` datetime DEFAULT NULL COMMENT '权重期限',
  `source` char(1) DEFAULT NULL COMMENT '来源（转载/原创）',
  `copyfrom` varchar(255) DEFAULT NULL COMMENT '文章来源出处',
  `hits` decimal(20,0) DEFAULT '0' COMMENT '点击数',
  `hits_plus` decimal(10,0) DEFAULT NULL COMMENT '支持数',
  `hits_minus` decimal(10,0) DEFAULT NULL COMMENT '反对数',
  `word_count` decimal(10,0) DEFAULT NULL COMMENT '字数（不包含html）',
  `custom_content_view` varchar(255) DEFAULT NULL COMMENT '自定义内容视图',
  `view_config` varchar(1000) DEFAULT NULL COMMENT '视图配置',
  `status` char(1) NOT NULL DEFAULT '0' COMMENT '状态（0正常 1删除 2停用）',
  `create_by` varchar(64) NOT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) NOT NULL COMMENT '更新者',
  `update_date` datetime NOT NULL COMMENT '更新时间',
  `remarks` varchar(500) DEFAULT NULL COMMENT '备注信息',
  `corp_code` varchar(64) NOT NULL DEFAULT '0' COMMENT '租户代码',
  `corp_name` varchar(100) NOT NULL DEFAULT 'JeeSite' COMMENT '租户名称',
  PRIMARY KEY (`id`),
  KEY `idx_cms_article_cb` (`create_by`),
  KEY `idx_cms_article_cc` (`category_code`),
  KEY `idx_cms_article_corp_code` (`corp_code`),
  KEY `idx_cms_article_status` (`status`),
  KEY `idx_cms_article_ud` (`update_date`),
  KEY `idx_cms_article_weight` (`weight`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='文章表';

-- ----------------------------
-- Records of js_cms_article
-- ----------------------------
BEGIN;
COMMIT;

