-- ----------------------------
-- Table structure for js_cms_comment
-- ----------------------------
DROP TABLE IF EXISTS `js_cms_comment`;
CREATE TABLE `js_cms_comment` (
  `id` varchar(64) NOT NULL COMMENT '编号',
  `category_code` varchar(64) NOT NULL COMMENT '栏目编码',
  `article_id` varchar(64) NOT NULL COMMENT '内容编号',
  `parent_id` varchar(64) DEFAULT NULL COMMENT '父级评论',
  `article_title` varchar(255) NOT NULL COMMENT '内容标题',
  `content` varchar(255) NOT NULL COMMENT '评论内容',
  `name` varchar(50) DEFAULT NULL COMMENT '评论姓名',
  `ip` varchar(100) DEFAULT NULL COMMENT '评论IP',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建者',
  `create_date` datetime NOT NULL COMMENT '创建时间',
  `audit_user_code` varchar(64) DEFAULT NULL COMMENT '审核人',
  `audit_date` datetime DEFAULT NULL COMMENT '审核时间',
  `audit_comment` varchar(200) DEFAULT NULL COMMENT '审核意见',
  `hits_plus` decimal(10,0) DEFAULT NULL COMMENT '支持数',
  `hits_minus` decimal(10,0) DEFAULT NULL COMMENT '反对数',
  `status` char(1) NOT NULL COMMENT '状态（0正常 1删除 2停用）',
  `corp_code` varchar(64) NOT NULL DEFAULT '0' COMMENT '租户代码',
  `corp_name` varchar(100) NOT NULL DEFAULT 'JeeSite' COMMENT '租户名称',
  PRIMARY KEY (`id`),
  KEY `idx_cms_comment_catc` (`category_code`),
  KEY `idx_cms_comment_ai` (`article_id`),
  KEY `idx_cms_comment_cc` (`corp_code`),
  KEY `idx_cms_comment_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='文章评论表';

