INSERT INTO `js_sys_config` (`id`, `config_name`, `config_key`, `config_value`, `is_sys`, `create_by`, `create_date`, `update_by`, `update_date`, `remarks`) VALUES ('1705054032687181824', '用户登录-登录失败多少次数后显示验证码', 'sys.login.failedNumAfterValidCode', '100', '0', 'system', '2023-09-22 10:58:54', 'system', '2023-09-22 10:58:54', '设置为0强制使用验证码登录');
